  --secondary-foreground: rgb(235, 228, 214);
  --muted: rgb(74, 68, 57);
  --muted-foreground: rgb(169, 160, 148);
  --accent: rgb(159, 142, 93);
  --accent-foreground: rgb(42, 37, 34);
  --destructive: rgb(180, 119, 107);
  --destructive-foreground: rgb(241, 234, 220);
  --border: rgb(88, 82, 70);
  --input: rgb(88, 82, 70);
  --ring: rgb(138, 161, 122);
  --chart-1: rgb(138, 161, 122);
  --chart-2: rgb(155, 176, 137);
  --chart-3: rgb(111, 133, 104);
  --chart-4: rgb(159, 142, 93);
  --chart-5: rgb(94, 111, 88);
  --radius: 0.425rem;
